public struct Home: Equatable, Hashable {
    /**
     * `None` when signed out.
     */
    public var account: Account?
    /**
     * `None` when there is no live plan (or before the first refresh).
     */
    public var plan: Plan?
    /**
     * The VPN account exists at the provider and can make configs.
     */
    public var vpnReady: Bool
    public var devicesActive: UInt32
    public var devicesLimit: UInt32
    public var connections: [Connection]
    /**
     * Filled by `load_locations`.
     */
    public var locations: [Location]
    /**
     * The server address used last, for the sign-in screen.
     */
    public var lastServer: String
    /**
     * Travel Hub destinations, filled by `load_destinations`.
     */
    public var destinations: [DestinationSummary]
    /**
     * Saved trips, newest first, filled by `load_trips`.
     */
    public var trips: [Trip]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * `None` when signed out.
         */account: Account?, 
        /**
         * `None` when there is no live plan (or before the first refresh).
         */plan: Plan?, 
        /**
         * The VPN account exists at the provider and can make configs.
         */vpnReady: Bool, devicesActive: UInt32, devicesLimit: UInt32, connections: [Connection], 
        /**
         * Filled by `load_locations`.
         */locations: [Location], 
        /**
         * The server address used last, for the sign-in screen.
         */lastServer: String, 
        /**
         * Travel Hub destinations, filled by `load_destinations`.
         */destinations: [DestinationSummary], 
        /**
         * Saved trips, newest first, filled by `load_trips`.
         */trips: [Trip]) {
        self.account = account
        self.plan = plan
        self.vpnReady = vpnReady
        self.devicesActive = devicesActive
        self.devicesLimit = devicesLimit
        self.connections = connections
        self.locations = locations
        self.lastServer = lastServer
        self.destinations = destinations
        self.trips = trips
    }

    

    
}

